public List<Double> runningMedian(int[] stream) {
    List<Integer> sorted = new ArrayList<>();
    List<Double> medians = new ArrayList<>();
    for (int x : stream) {
        int pos = Collections.binarySearch(sorted, x);
        if (pos < 0) pos = -(pos + 1);
        sorted.add(pos, x);
        int m = sorted.size();
        double median;
        if (m % 2 == 1) {
            median = sorted.get(m / 2);
        } else {
            median = (sorted.get(m / 2 - 1) + sorted.get(m / 2)) / 2.0;
        }
        medians.add(median);
    }
    return medians;
}

