import bisect

def running_median(stream: list[int]) -> list[float]:
    sorted_vals: list[int] = []
    medians: list[float] = []
    for x in stream:
        bisect.insort(sorted_vals, x)
        m = len(sorted_vals)
        if m % 2 == 1:
            median = float(sorted_vals[m // 2])
        else:
            median = (sorted_vals[m // 2 - 1] + sorted_vals[m // 2]) / 2.0
        medians.append(median)
    return medians

