import heapq

def running_median(stream: list[int]) -> list[float]:
    lower: list[int] = []  # max-heap via negation
    upper: list[int] = []  # min-heap
    medians: list[float] = []
    for x in stream:
        if not lower or x <= -lower[0]:
            heapq.heappush(lower, -x)
        else:
            heapq.heappush(upper, x)
        if len(lower) > len(upper) + 1:
            heapq.heappush(upper, -heapq.heappop(lower))
        elif len(upper) > len(lower):
            heapq.heappush(lower, -heapq.heappop(upper))
        if len(lower) == len(upper):
            median = (-lower[0] + upper[0]) / 2.0
        else:
            median = float(-lower[0])
        medians.append(median)
    return medians
